const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const washingtonDC = ee.Geometry.Point([-77.0369, 38.9072]);

  // Define date ranges for each day
  const jan29 = ee.Date('2019-01-29');
  const feb5 = ee.Date('2019-02-05');

  // 2. Data Acquisition - ERA5-Land for temperature
  const era5Temp = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .select('temperature_2m');

  // Get images for January 29
  const jan29Collection = era5Temp
    .filterDate(jan29, jan29.advance(1, 'day'))
    .filterBounds(washingtonDC);

  // Get images for February 5  
  const feb5Collection = era5Temp
    .filterDate(feb5, feb5.advance(1, 'day'))
    .filterBounds(washingtonDC);

  // Check collection sizes
  const jan29Size = jan29Collection.size().getInfo();
  const feb5Size = feb5Collection.size().getInfo();

  console.log(`Jan 29 Images: ${jan29Size}, Feb 5 Images: ${feb5Size}`);

  if (jan29Size === 0 || feb5Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean temperature for each day
  const jan29Mean = jan29Collection.mean();
  const feb5Mean = feb5Collection.mean();

  // Get temperature values
  const jan29Temp = jan29Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washingtonDC,
    scale: 1000
  }).get('temperature_2m');

  const feb5Temp = feb5Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washingtonDC,
    scale: 1000
  }).get('temperature_2m');

  // Get pixel count for validation
  const pixelCount = jan29Mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: washingtonDC,
    scale: 1000
  }).get('temperature_2m');

  const jan29Val = jan29Temp.getInfo();
  const feb5Val = feb5Temp.getInfo();
  const count = pixelCount.getInfo();

  console.log(`Jan 29 Temp: ${jan29Val ? jan29Val.toFixed(2) : 'N/A'}°C`);
  console.log(`Feb 5 Temp: ${feb5Val ? feb5Val.toFixed(2) : 'N/A'}°C`);
  console.log(`Valid pixels: ${count}`);

  // 5. Validation & Final Answer
  if (jan29Val === null || feb5Val === null || 
      isNaN(jan29Val) || isNaN(feb5Val) || count === 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  const tempDiff = Math.abs(jan29Val - feb5Val);
  console.log(`Temperature difference: ${tempDiff.toFixed(2)}°C`);

  if (tempDiff >= 24) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
